import{_ as t,c as s,af as a,o as i}from"./chunks/framework.BOn264RY.js";const u=JSON.parse('{"title":"Getting started","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://tsed.dev/introduction/getting-started.html"}]]},"headers":[],"relativePath":"introduction/getting-started.md","filePath":"introduction/getting-started.md","lastUpdated":1788515248000}'),o={name:"introduction/getting-started.md"};function n(d,e,r,l,c,p){return i(),s("div",null,[...e[0]||(e[0]=[a(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /introduction/getting-started.md for this page in Markdown format</div><h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>Ts.ED ships an opinionated CLI runtime that can scaffold full Ts.ED applications, automate everyday chores, and even expose its capabilities over MCP. If you want the bigger architectural picture before diving in, start with the <a href="/guide/cli/overview.html">CLI overview</a> and then come back here to get hands-on.</p><h2 id="core-building-blocks" tabindex="-1">Core building blocks <a class="header-anchor" href="#core-building-blocks" aria-label="Permalink to &quot;Core building blocks&quot;">​</a></h2><p>The CLI runtime layers <code>@tsed/cli-core</code> with optional packages so you can dial in as much interactivity as you need:</p><ul><li><code>@tsed/cli-core</code> loads the Ts.ED DI container (or your own), resolves commands, and discovers plugins at runtime.</li><li><code>@tsed/cli-prompts</code> lets you orchestrate conversational flows with shareable prompt providers.</li><li><code>@tsed/cli-tasks</code> runs ordered task lists and streams progress/logs in the terminal.</li><li><code>@tsed/cli-mcp</code> wraps the same DI context in a Model Context Protocol server so AI agents can call your tools safely.</li></ul><p>Every example in the CLI guides works in two contexts:</p><ul><li><strong>Ts.ED projects</strong> created via <code>tsed init</code> keep using the default DI container plus any framework services you register.</li><li><strong>Standalone CLIs</strong> that import <code>@tsed/cli-core</code> can register identical commands/prompts/tasks without pulling in the rest of Ts.ED. You decide which packages to include.</li></ul><h2 id="install-the-cli-binary" tabindex="-1">Install the CLI binary <a class="header-anchor" href="#install-the-cli-binary" aria-label="Permalink to &quot;Install the CLI binary&quot;">​</a></h2><p>Install globally or add it to your devDependencies:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @tsed/cli</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or, inside a repository</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --save-dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @tsed/cli</span></span></code></pre></div><p>The binary exposes <code>tsed</code> for classic shell use and <code>tsed-mcp</code> for launching the bundled MCP server.</p><h2 id="bootstrap-a-project-quickly" tabindex="-1">Bootstrap a project quickly <a class="header-anchor" href="#bootstrap-a-project-quickly" aria-label="Permalink to &quot;Bootstrap a project quickly&quot;">​</a></h2><p>Use the <code>tsed</code> executable to explore commands or scaffold a new service:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tsed</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tsed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-api</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-api</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tsed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # or yarn start</span></span></code></pre></div><p>The generator walks you through prompts (powered by <code>@tsed/cli-prompts</code>) and streams build steps through <code>@tsed/cli-tasks</code>. Popular integrations—Jest, Mocha, ESLint/Prettier, Passport, and more—are available out of the box via official CLI plugins, and you can install community plugins later simply by adding them to <code>package.json</code>.</p><h2 id="build-your-own-cli-with-tsed-cli-core" tabindex="-1">Build your own CLI with <code>@tsed/cli-core</code> <a class="header-anchor" href="#build-your-own-cli-with-tsed-cli-core" aria-label="Permalink to &quot;Build your own CLI with \`@tsed/cli-core\`&quot;">​</a></h2><p>Want the runtime without the Ts.ED framework template? Install <code>@tsed/cli-core</code> (plus whichever companion packages you need) inside any TypeScript project:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @tsed/cli-core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @tsed/cli-prompts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @tsed/cli-tasks</span></span></code></pre></div><p>Define commands with the decorator API, register prompts/tasks, and optionally expose the same tools through <code>@tsed/cli-mcp</code>. Because the DI container is configurable, you can:</p><ul><li>bootstrap a pure CLI that only relies on your own services, or</li><li>reuse the existing Ts.ED DI modules from a server project.</li></ul><p>All of the snippets referenced throughout the CLI documentation—prompts, tasks, MCP servers—work in both setups. Swap in your own providers during bootstrap to keep logic shared between multiple CLIs or between the CLI and your backend services.</p><p>Need to run the CLI behind a corporate proxy or custom network stack? Check the <a href="./configuration.html">configuration guide</a> for the supported npm config keys and environment variables.</p><h2 id="built-in-commands" tabindex="-1">Built-in commands <a class="header-anchor" href="#built-in-commands" aria-label="Permalink to &quot;Built-in commands&quot;">​</a></h2><p>The <code>tsed</code> binary ships with several commands across project scaffolding, generators, and maintenance tasks:</p><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>tsed init [root]</code></td><td>Scaffold a new Ts.ED project with prompts and templates.</td></tr><tr><td><code>tsed init-options</code></td><td>Print every <code>tsed init</code> flag (handy for CI or tooling).</td></tr><tr><td><code>tsed generate [type] [name]</code> / <code>tsed g</code></td><td>Run a generator template (controllers, services, custom templates, etc.).</td></tr><tr><td><code>tsed template [name]</code></td><td>Create or scaffold a <code>defineTemplate()</code> file inside <code>.templates/</code>.</td></tr><tr><td><code>tsed add [name]</code></td><td>Install a CLI plugin (e.g., <code>@tsed/cli-plugin-&lt;feature&gt;</code>).</td></tr><tr><td><code>tsed run &lt;command&gt;</code></td><td>Proxy to project-level scripts (with SWC already wired).</td></tr><tr><td><code>tsed update</code></td><td>Update Ts.ED packages used by the current project.</td></tr><tr><td><code>tsed mcp [options]</code></td><td>Launch the bundled MCP server (stdio or HTTP).</td></tr></tbody></table><p>See <code>tsed --help</code> for the latest list, or read the <a href="/guide/cli/commands.html">Commands guide</a> for every decorator/<code>command()</code> option.</p>`,27)])])}const k=t(o,[["render",n]]);export{u as __pageData,k as default};
